+    offset+=4;
+
+    /* uint32_t duration_nsec; */
+    proto_tree_add_item(tree, hf_openflow_flow_removed_duration_nsec, tvb, offset, 4, ENC_BIG_ENDIAN);
+    offset+=4;
+
+    /* uint16_t idle_timeout; */
